return ['domain'=>'tranzly','plural-forms'=>'nplurals=1; plural=0;','language'=>'ms_MY','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress berbilang bahasa, satu hantaran setiap bahasa: terjemahan hantaran, halaman, kategori, teks media, widget dan tajuk tapak yang dipautkan, dengan terjemahan Tranzly lama anda diimport.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Penyedia AI','The makers of ChatGPT. A good all-rounder.'=>'Pencipta ChatGPT. Pilihan pelbagai guna yang baik.','The makers of Claude. Strong at writing and careful reasoning.'=>'Pembuat Claude. Handal dalam penulisan dan penaakulan yang teliti.','Google\'s Gemini models. Fast and inexpensive.'=>'Model Gemini daripada Google. Pantas dan murah.','A European AI company with fast, inexpensive models.'=>'Sebuah syarikat AI Eropah dengan model yang pantas dan murah.','Low-cost models that are good at writing and code.'=>'Model kos rendah yang bagus dalam penulisan dan kod.','One key for models from many different providers.'=>'Satu kunci untuk model daripada pelbagai pembekal yang berbeza.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Sebarang perkhidmatan yang berfungsi seperti API OpenAI, termasuk model yang berjalan pada komputer atau pelayan anda sendiri.','General (used when nothing more specific is set)'=>'Umum (digunakan apabila tiada yang lebih khusus ditetapkan)','Writing and rewriting'=>'Menulis dan menulis semula','Translation'=>'Terjemahan','Code and CSS'=>'Kod dan CSS','Sorry, you are not allowed to access this page.'=>'Maaf, anda tidak dibenarkan mengakses halaman ini.','These settings are shared by every plugin that uses them: %s.'=>'Tetapan ini dikongsi oleh setiap palam masuk yang menggunakannya: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Kekunci anda disulitkan dalam pangkalan data tapak ini dan hanya dihantar kepada pembekal yang anda pilih — tidak pernah kepada kami.','Step 1 of 2: choose an AI provider'=>'Langkah 1 daripada 2: pilih pembekal AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Anda membawa kunci anda sendiri, jadi anda membayar penyedia secara terus untuk apa yang anda guna. Tidak pasti? Mana-mana pilihan ini berfungsi dengan baik; anda boleh menambah lagi kemudian.','Next'=>'Seterusnya','Step 2 of 2: connect %s'=>'Langkah 2 daripada 2: sambungkan %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Masukkan alamat perkhidmatan yang serasi dengan OpenAI anda, diakhiri dengan /v1. Kunci hanya diperlukan jika perkhidmatan tersebut memintanya.','Open %s and sign in (or create a free account).'=>'Buka %s dan log masuk (atau buat akaun percuma).','the %s API keys page'=>'halaman kekunci API %s','Create a new key and copy it.'=>'Cipta kunci baharu dan salin.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Tampal di bawah dan tekan "Simpan dan uji". Kami menghantar satu permintaan kecil untuk menyemak ia berfungsi.','Most providers need a little credit on the account before a key works: %s.'=>'Kebanyakan pembekal memerlukan sedikit kredit pada akaun sebelum kunci berfungsi: %s.','add credit'=>'tambah kredit','← Choose a different provider'=>'← Pilih pembekal lain','Address'=>'Alamat','Saved key ends in …%s — paste a new one to replace it'=>'Kunci yang disimpan berakhir dengan …%s — tampal yang baharu untuk menggantikannya','Key (optional)'=>'Kunci (pilihan)','API key'=>'Kunci API','Save and test'=>'Simpan dan uji','Providers'=>'Pembekal','Provider'=>'Penyedia','Status'=>'Status','Key'=>'Kunci','Get a key'=>'Dapatkan kekunci','Test'=>'Uji','Remove'=>'Buang','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Disimpan oleh versi plugin yang lebih baharu: kemas kini plugin ini, atau masukkan semula kekunci tersebut.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Kunci yang disimpan tidak lagi boleh dibuka (kunci keselamatan tapak telah berubah). Masukkannya semula.','Not connected'=>'Tidak disambungkan','Connected — last test passed %s'=>'Disambungkan — ujian terakhir lulus %s','Last test failed: %s'=>'Ujian terakhir gagal: %s','Connected — not tested yet'=>'Bersambung — belum diuji','Which model to use'=>'Model manakah yang hendak digunakan','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ menandakan cadangan kami untuk tugasan tersebut. Senarai ini merangkumi setiap model yang boleh digunakan oleh kunci anda, dibaca secara langsung daripada pembekal.','— Recommended for the provider —'=>'— Disyorkan untuk penyedia —','Save models'=>'Simpan model','Refresh the model lists from the providers'=>'Muat semula senarai model daripada pembekal','best quality'=>'kualiti terbaik','lowest cost'=>'kos terendah','fastest'=>'paling pantas','Add a model yourself'=>'Tambah model sendiri','A model came out today? Paste its exact name to use it straight away.'=>'Model baharu dikeluarkan hari ini? Tampal nama tepatnya untuk menggunakannya serta-merta.','Model name'=>'Nama model','Add model'=>'Tambah model','Recommended models list'=>'Senarai model yang disyorkan','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Senarai model yang disyorkan tidak dapat disahkan, jadi tiada cadangan yang ditunjukkan. Pasang semula palam masuk, atau dayakan kemas kini harian di bawah.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Senarai yang sedang digunakan telah diterbitkan pada %s. Setiap kemas kini palam masuk membawakan yang baharu.','Also check Zinn Digital® once a day for an updated list.'=>'Sila semak juga Zinn Digital® sekali sehari untuk senarai yang dikemas kini.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Hanya permintaan muat turun biasa dihantar: tiada kunci, tiada alamat tapak, tiada apa-apa tentang kandungan anda. Senarai tersebut ditandatangani, dan senarai yang gagal dalam semakan tandatangan akan diabaikan.','Last checked %1$s: %2$s.'=>'Kali terakhir disemak %1$s: %2$s.','Save, and check now if turned on'=>'Simpan, dan semak sekarang jika dihidupkan','a newer list was installed'=>'senarai yang lebih baharu telah dipasang','already up to date'=>'sudah dikemas kini','the download failed the signature check and was ignored'=>'muat turun gagal dalam pemeriksaan tandatangan dan diabaikan','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® tidak dapat dihubungi; senarai semasa terus digunakan','turned off'=>'ditutup','Open'=>'Buka','Check their status page'=>'Semak halaman status mereka','Open your billing page'=>'Buka halaman pengebilan anda','Open your API keys page'=>'Buka halaman kunci API anda','Open the AI settings'=>'Buka tetapan AI','Sorry, you are not allowed to do that.'=>'Maaf, anda tidak dibenarkan berbuat demikian.','Unknown provider.'=>'Penyedia tidak diketahui.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Masukkan alamat perkhidmatan anda, sebagai contoh http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Itu tidak kelihatan seperti kunci API. Salin sekali lagi, tanpa ruang.','Paste your API key first.'=>'Tampal kunci API anda terlebih dahulu.','Key removed.'=>'Kunci telah dialih keluar.','Models saved.'=>'Model disimpan.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Masukkan nama tepat model tersebut, contohnya seperti yang ditulis dalam dokumentasi pembekal.','Added %s. Choose it under "Which model to use".'=>'%s telah ditambah. Pilihnya di bawah "Model mana yang hendak digunakan".','Model removed.'=>'Model dialih keluar.','Daily updates are off. The list that came with the plugin is used.'=>'Kemas kini harian dimatikan. Senarai yang disertakan bersama palam masuk itu digunakan.','Checked: %s.'=>'Disemak: %s.','Model lists refreshed.'=>'Senarai model telah segar semula.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Kunci AI anda telah disimpan oleh versi yang lebih baharu bagi salah satu palam masuk anda. Kemas kini palam masuk ini, atau masukkan semula kunci dalam tetapan AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Kunci AI anda yang disimpan tidak lagi boleh dibuka (kunci keselamatan tapak telah berubah). Masukkan ia semula dalam tetapan AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI belum disediakan. Tambah kunci untuk pembekal AI dalam tetapan AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Tiada model dipilih untuk tugasan ini. Pilih satu dalam tetapan AI.','That AI provider is not supported by this version of the plugin.'=>'Penyedia AI tersebut tidak disokong oleh versi plugin ini.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tapak ini tidak dapat menghubungi perkhidmatan AI anda. Semak sama ada ia sedang berjalan dan alamatnya boleh diakses dari pelayan web anda (perkhidmatan pada komputer anda sendiri tidak boleh diakses dari tapak yang dihoskan).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tapak ini tidak dapat menghubungi %s. Semak halaman status mereka; jika ia aktif, hos anda mungkin menyekat sambungan keluar, atau alamat tersebut salah.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s menyatakan bahawa akaun anda tiada baki kredit atau kuota lagi. Tambah kredit atau naikkan had anda dalam akaun anda bersama mereka, kemudian cuba lagi.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s tidak menerima kunci anda. Kunci tersebut mungkin tersalah taip, ditarik balik atau telah tamat tempoh. Buat kunci baharu dan tampalkannya di sini.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s menolak permintaan ini untuk kunci anda. Kunci tersebut mungkin tidak mempunyai akses kepada model atau ciri ini, atau akaun anda perlu disahkan.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" tidak tersedia daripada %2$s untuk kunci anda. Pilih model lain dalam tetapan AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Pelan %2$s anda tidak merangkumi model "%1$s". Pilih model lain dalam tetapan AI, atau tingkatkan pelan anda bersama mereka.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s mengehadkan kelajuan kunci anda menghantar permintaan. Tunggu seminit dan cuba lagi, atau tingkatkan had kadar anda dengan mereka.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s sedang menghadapi masalah sekarang (gangguan atau beban lampau pada pihak mereka). Tiada apa-apa yang tidak kena dengan tetapan anda. Cuba sebentar lagi.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Permintaan AI gagal atas sebab yang tidak dapat kami kenal pasti. Cuba lagi; jika ia terus berlaku, hubungi sokongan dengan butiran di bawah.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Penyedia AI menjawab dalam bentuk yang tidak dapat dibaca oleh palam ini. Cuba lagi; jika ia terus berlaku, pilih model lain atau hubungi sokongan.','Custom (OpenAI-compatible)'=>'Tersuai (serasi OpenAI)','Save a key for this provider first.'=>'Simpan kunci untuk penyedia ini dahulu.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Kunci anda berfungsi, tetapi pembekal tidak menyenaraikan sebarang model teks untuknya. Tambah model sendiri di bawah.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Disambungkan. %1$s menjawab menggunakan %2$s. Ciri AI anda sedia untuk digunakan.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Peranan pengguna anda tidak dibenarkan menggunakan AI pada tapak ini. Sila tanya pentadbir.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tapak web ini telah mencapai had perbelanjaan AI bulanan. Pentadbir boleh meningkatkannya dalam tetapan AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tapak web ini telah mencapai had bulanan permintaan AI. Pentadbir boleh meningkatkannya dalam tetapan AI.','Usage and cost'=>'Penggunaan dan kos','The log, limits and role permissions apply to AI used through: %s.'=>'Log, had dan kebenaran peranan terpakai pada AI yang digunakan melalui: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kos adalah anggaran, dikira daripada harga yang diterbitkan; model tanpa harga yang diketahui dikira sebagai sifar.','This month: %1$s requests, about %2$s.'=>'Bulan ini: %1$s permintaan, kira-kira %2$s.','When'=>'Bila','Who'=>'Siapa','Used for'=>'Digunakan untuk','Model'=>'Model','Tokens in / out'=>'Token masuk / keluar','About'=>'Mengenai','Result'=>'Keputusan','No AI requests have been made yet.'=>'Tiada permintaan AI telah dibuat lagi.','Done'=>'Selesai','Limits and permissions'=>'Had dan kebenaran','Monthly spending limit (US dollars)'=>'Had bulanan (Dolar US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Biarkan kosong untuk tiada had. AI akan berhenti untuk baki bulan tersebut sebaik sahaja anggaran kos mencecahnya.','Monthly request limit'=>'Had bulanan permintaan','Leave empty for no limit.'=>'Biarkan kosong untuk tiada had.','Who may use AI'=>'Siapa yang boleh menggunakan AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Tanda kosongkan untuk membenarkan semua orang yang boleh menggunakan ciri-ciri plugin tersebut menggunakan AI. Pentadbir sentiasa boleh menggunakannya.','Save limits and permissions'=>'Simpan had dan kebenaran','Limits and permissions saved.'=>'Had dan kebenaran disimpan.','That language is not one of this site\'s languages.'=>'Bahasa tersebut bukan salah satu bahasa tapak web ini.','A translation must be the same kind of content as the original.'=>'Terjemahan mestilah jenis kandungan yang sama dengan yang asal.','Choose one of the site\'s other languages.'=>'Pilih salah satu bahasa lain tapak web ini.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skrip skrin pentadbir hilang daripada salinan plugin ini. Pasang semula daripada pakej yang dikeluarkan.','This screen needs JavaScript.'=>'Skrin ini memerlukan JavaScript.','Choose a language'=>'Pilih bahasa','Upgrade'=>'Naik taraf','Pricing'=>'Harga','Start Trial'=>'Mulakan Percubaan','Account'=>'Akaun','Contact Us'=>'Hubungi Kami','Affiliation'=>'Gabungan','the kind of softwarePlugin'=>'Pelayan Palam','greetingHey %s,'=>'Hai %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Langgan untuk menerima pemberitahuan e-mel untuk kemas kini keselamatan & ciri, kandungan pendidikan dan tawaran sekali-sekala, serta untuk berkongsi beberapa maklumat asas persekitaran WordPress. Ini akan membantu kami menjadikan %s lebih serasi dengan tapak anda dan lebih baik dalam melakukan apa yang anda perlukan.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Sertai untuk menerima pemberitahuan e-mel bagi kemas kini keselamatan & ciri, kandungan pendidikan dan tawaran sekali-sekala, serta untuk berkongsi beberapa maklumat asas persekitaran WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Jika anda melangkau ini, tidak mengapa! %1$s akan tetap berfungsi dengan baik.','Allow & Continue'=>'Benarkan & Teruskan','verbSkip'=>'Langkau','Skipping, please wait'=>'Melangkau, sila tunggu','Continue'=>'Teruskan','Please wait'=>'Sila tunggu','as activating pluginActivating'=>'Sedang mengaktifkan','This will allow %s to'=>'Ini akan membenarkan %s untuk','Privacy Policy'=>'Dasar Privasi','Terms of Service'=>'Syarat Perkhidmatan','License Agreement'=>'Perjanjian Lesen','Have a license key?'=>'Ada kunci lesen?','Activate License'=>'Aktifkan Lesen','View Basic Profile Info'=>'Lihat Maklumat Profil Asas','Your WordPress user\'s: first & last name, and email address'=>'Pengguna WordPress anda: nama pertama & terakhir, dan alamat e-mel','View Basic Website Info'=>'Lihat Maklumat Asas Laman Web','Homepage URL & title, WP & PHP versions, and site language'=>'URL & tajuk Laman Utama, versi WP & PHP, serta bahasa tapak','View Basic %s Info'=>'Lihat Maklumat Asas %s','Current %s & SDK versions, and if active or uninstalled'=>'Versi %s & SDK semasa, dan sama ada aktif atau dinyahpasang','Newsletter'=>'Surat Berita','Updates, announcements, marketing, no spam'=>'Kemas kini, pengumuman, pemasaran, tiada spam','View Diagnostic Info'=>'Lihat Maklumat Diagnostik','WordPress & PHP versions, site language & title'=>'Versi WordPress & PHP, bahasa & tajuk laman','View Plugins & Themes List'=>'Lihat Senarai Palam & Tema','Names, slugs, versions, and if active or not'=>'Nama, slug, versi, dan sama ada aktif atau tidak','optional'=>'pilihan','Never miss an important update'=>'Jangan terlepas kemas kini penting','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Kami telah memperkenalkan pilihan opt-in ini supaya anda tidak terlepas kemas kini penting dan membantu kami menjadikan %s lebih serasi dengan tapak anda serta lebih cekap melakukan perkara yang anda perlukan.','Thank you for updating to %1$s v%2$s!'=>'Terima kasih kerana mengemas kini kepada %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Awalan mestilah terdiri daripada 1 hingga 8 huruf kecil atau digit, bermula dengan huruf, dan tidak boleh menamakan plugin tersebut.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" bukan kod bahasa. Gunakan lokal WordPress seperti fr_FR atau de_DE.','List at least one language.'=>'Senaraikan sekurang-kurangnya satu bahasa.','You are not allowed to translate this item.'=>'Anda tidak dibenarkan menterjemah item ini.','This item already has a version in that language.'=>'Item ini sudah mempunyai versi dalam bahasa tersebut.','That translation engine is not available on this site.'=>'Enjin terjemahan tersebut tidak tersedia di tapak ini.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Enjin yang berbeza bagi setiap bahasa, geganti automatik dan had perbelanjaan ialah ciri Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Setiap bahasa mestilah salah satu bahasa tapak, dengan enjin yang tersedia.','The fallback list may only name available engines.'=>'Senarai sandaran hanya boleh menamakan enjin yang tersedia.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Had bulanan ialah jumlah dalam US dolar, sifar atau lebih, untuk enjin yang tersedia.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Terjemahan pilihan dan nada mengikut bahasa ialah ciri Tranzly Pro. Senarai jangan-terjemah adalah percuma.','Glossary entries must be grouped by one of the site\'s languages.'=>'Entri glosari mesti dikumpulkan mengikut salah satu bahasa tapak web tersebut.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Nada ditetapkan mengikut bahasa tapak: lalai formaliti, lebih atau kurang, berserta arahan pilihan.','The value for %s is not one of the allowed choices.'=>'Nilai untuk %s bukan salah satu pilihan yang dibenarkan.','The background queue is not available on this site.'=>'Baris giliran latar belakang tidak tersedia pada tapak ini.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Tkerja terjemahan berjalan sebagai orang yang memulakannya, jadi pengguna mesti log masuk.','There is nothing you are allowed to translate in that selection.'=>'Tiada apa pun yang dibenarkan untuk anda terjemah dalam pilihan itu.','That item is not part of a translation job.'=>'Item tersebut bukan sebahagian daripada tugasan terjemahan.','You are not allowed to change that translation.'=>'Anda tidak dibenarkan menukar terjemahan itu.','This item\'s group already has a %1$s version (#%2$d).'=>'Kumpulan item ini sudah mempunyai versi %1$s (#%2$d).','An item cannot be its own translation.'=>'Sesuatu item tidak boleh menjadi terjemahannya sendiri.','That item is already a translation of something else. Unlink it first.'=>'Item itu sudah pun menjadi terjemahan bagi perkara lain. Buat nyahpautan terlebih dahulu.','The translation link could not be saved.'=>'Pautan terjemahan tidak dapat disimpan.','That text cannot be translated here.'=>'Teks tersebut tidak boleh diterjemahkan di sini.','That media text cannot be translated here.'=>'Teks media tersebut tidak boleh diterjemahkan di sini.','A translation can be published or kept as a draft.'=>'Terjemahan boleh diterbitkan atau disimpan sebagai draf.','You are not allowed to publish this kind of content.'=>'Anda tidak dibenarkan menerbitkan jenis kandungan ini.','This item is already written in that language.'=>'Item ini sudah pun ditulis dalam bahasa tersebut.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Terjemahan ini telah diedit oleh seseorang (atau diimport), jadi ia dilindungi. Nyahkuncinya untuk menterjemahkannya semula.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Tiada enjin terjemahan yang disediakan lagi. Tambah kekunci untuk satu dalam Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Enjin terjemahan itu belum disediakan lagi: tambahkan kekuncinya dahulu.','The same text is being translated by another job right now; this item will use that answer.'=>'Teks yang sama sedang diterjemahkan oleh tugasan lain sekarang; item ini akan menggunakan jawapan tersebut.','No translation engine could take this item.'=>'Tiada enjin terjemahan yang boleh mengambil item ini.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Enjin tidak mengembalikan terjemahan untuk setiap bahagian item ini. Tiada apa-apa yang diubah.','AI model'=>'Model AI','AI model (%1$s %2$s)'=>'Model AI (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s sedang menghadapi masalah sekarang. Cuba semula sebentar lagi, atau guna enjin lain.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Tapak anda tidak dapat menghubungi %s. Semak sama ada ia boleh membuat sambungan keluar, kemudian cuba lagi.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s tidak menerima kunci API anda. Semak kunci tersebut dalam Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Akaun %s anda telah kehabisan kuota atau baki. Tambah nilai dengannya, atau gunakan enjin lain.','%s asked us to slow down. It will be tried again automatically.'=>'%s meminta kami memperlahankan proses. Ia akan dicuba semula secara automatik.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Teks ini terlalu panjang untuk %s dalam satu masa. Bahagikan kandungan, atau gunakan enjin lain.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s enggan menterjemahkan kandungan ini. Cuba enjin lain, atau terjemahkannya secara manual.','%s does not translate this language. Choose another engine for it.'=>'%s tidak menterjemahkan bahasa ini. Pilih enjin lain untuknya.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Had bulanan untuk %s telah dicapai, jadi tiada lagi yang dihantar kepadanya. Tingkatkan had dalam Tranzly → Engines, atau tunggu sehingga bulan depan.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Terjemahan dengan %s gagal atas sebab yang tidak dapat dikenal pasti oleh Tranzly. Butirannya adalah di bawah.','An engine id must be lowercase letters, digits and hyphens.'=>'ID enjin mestilah huruf kecil, nombor, dan tanda sempang.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Dibina oleh Neil Lock, Ketua Pegawai Eksekutif Zinn Digital® Ltd','Version %s'=>'Versi %s','Tranzly website'=>'Laman web Tranzly','Zinn Digital® website'=>'laman web Zinn Digital®','Settings saved.'=>'Tetapan disimpan.','See the Pro plans and pricing'=>'Lihat pelan dan harga Pro','Languages'=>'Bahasa','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Bahasa pertama ialah bahasa yang digunakan untuk kandungan anda. Pengunjung boleh bertukar menggunakan blok penukar bahasa.','(default)'=>'(lalai)','Locale code'=>'Kod lokapos','For example fr_FR'=>'Contohnya fr_FR','Name (optional)'=>'Nama (pilihan)','For example Français'=>'Contohnya Français','Add language'=>'Tambah bahasa','Front-end output'=>'Keluaran bahagian hadapan','Class name prefix'=>'Prefiks nama kelas','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Setiap nama kelas yang dicetak oleh palam masuk pada halaman anda bermula dengan awalan ini, supaya halaman tidak mendedahkan palam masuk yang membina halaman tersebut. 1 hingga 8 huruf kecil atau digit, bermula dengan huruf.','Beta updates'=>'Kemas kini beta','This site receives beta versions as updates.'=>'Tapak ini menerima versi beta sebagai kemas kini.','This site receives stable versions only.'=>'Laman web ini hanya menerima versi stabil.','Change this on the Account page'=>'Tukar ini pada halaman Akaun','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Versi beta ditawarkan kepada pemasangan Pro berlesen yang disambungkan ke akaun mereka. Setelah disambungkan, anda boleh menyertai dari halaman Akaun.','Save settings'=>'Simpan tetapan','First engine that is set up'=>'Enjin pertama yang disediakan','Key saved. It is stored encrypted and never shown again.'=>'Kunci disimpan. Ia disimpan secara disulitkan dan tidak akan ditunjukkan lagi.','Engine settings saved.'=>'Tetapan enjin berjaya disimpan.','Glossary saved.'=>'Glosari disimpan.','Your keys'=>'Kunci anda','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly memanggil perkhidmatan terjemahan menggunakan akaun anda sendiri. Kunci disimpan secara disulitkan dalam pangkalan data anda dan hanya dihantar kepada perkhidmatan yang berkenaan sahaja. Kunci model AI ditetapkan dalam tetapan AI.','%s API key'=>'Kunci API %s','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Disimpan: %s. Masukkan kekunci baharu untuk menggantikannya, atau simpan medan kosong untuk mengeluarkannya.','No key saved.'=>'Tiada kekunci disimpan.','Azure region (leave empty for a global resource)'=>'Wilayah Azure (biarkan kosong untuk sumber global)','Save key'=>'Simpan kunci','Check my DeepL usage'=>'Semak penggunaan DeepL saya','%1$s of %2$s characters used this billing period.'=>'%1$s daripada %2$s aksara digunakan untuk tempoh pengebilan ini.','Which engine translates'=>'Enjin manakah yang menterjemah','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Tiada enjin yang disediakan lagi. Simpan kekunci di atas (atau sediakan model AI) untuk mula menterjemah.','Default engine'=>'Enjin lalai','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Enjin yang berbeza bagi setiap bahasa, sandaran automatik dan had perbelanjaan bulanan ialah ciri Tranzly Pro.','Engine for %s'=>'Enjin untuk %s','The default engine'=>'Enjin lalai','If an engine fails or reaches a limit, try these next, in this order'=>'Jika enjin gagal atau mencapai had, cuba langkah berikut mengikut tertib ini','Monthly spending caps'=>'Had تخصيص perbelanjaan bulanan','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Apabila enjin mencapai hadnya, tiada lagi yang dihantar kepadanya sehingga bulan depan dan laporan terjemahan yang gagal menyatakan sebabnya. Biarkan kosong jika tiada had.','%1$s (spent this month: $%2$s)'=>'%1$s (telah dibelanjakan bulan ini: $%2$s)','Save caps'=>'Simpan had','Glossary and words never translated'=>'Glosari dan perkataan yang tidak pernah diterjemahkan','Never translate these words (one per line)'=>'Jangan sekali-kali terjemahkan perkataan ini','Brand and product names stay exactly as they are, with every engine.'=>'Nama jenama dan produk kekal seperti sediakala, dengan setiap enjin.','Preferred translations and tone per language are Tranzly Pro features.'=>'Terjemahan pilihan dan nada mengikut bahasa ialah ciri Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Terjemahan pilihan (satu setiap baris: terma = terjemahan)','Formality'=>'Kekomiran','Default'=>'Lalai','Formal'=>'Rasmi','Informal'=>'Tidak Rasmi','Style instructions (audience, brand voice)'=>'Arahan gaya (kandungan, nada jenama)','Save glossary'=>'Simpan glosari','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Kerja dimulakan dengan %d terjemahan untuk dilakukan. Ia berjalan di latar belakang: anda boleh menutup halaman ini.','Queued again.'=>'Dimasukkan ke baris gilir semula.','Running'=>'Sedang berjalan','Finished'=>'Selesai','Cancelled'=>'Dibatalkan','Translate in the background'=>'Terjemah di latar belakang','Set up a translation engine in the Engines tab first.'=>'Sediakan enjin terjemahan dalam tab Enjin terlebih dahulu.','Translate every'=>'Terjemah setiap','Into'=>'Ke dalam','With'=>'Dengan','Each language’s own engine'=>'Enjin setiap bahasa tersendiri','Publish the translations (otherwise they are saved as drafts)'=>'Terbitkan terjemahan tersebut (jika tidak, ia akan disimpan sebagai draf)','Estimate the cost'=>'Anggarkan kos','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d hantaran, %2$s aksara. Harga untuk enjin ini tidak diketahui lebih awal.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d hantaran, %2$s aksara: kira-kira $%3$s pada akaun anda sendiri.','Start translating'=>'Mula menterjemah','Jobs'=>'Kerja','No translation jobs yet.'=>'Tiada tugasan terjemahan lagi.','Job %1$d — %2$s'=>'Pekerjaan %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d daripada %2$d diterjemahkan, %3$d gagal, %4$d dilangkau (dilindungi atau sudah dalam bahasa tersebut)','Stop this job'=>'Hentikan tugasan ini','See what failed and why'=>'Lihat perkara yang gagal dan sebabnya','Content'=>'Kandungan','Language'=>'Bahasa','What went wrong'=>'Apa yang tidak kena','Fix it'=>'Betulkan','Details'=>'Butiran','Retry with'=>'Cuba semula dengan','The same engine'=>'Enjin yang sama','Retry'=>'Cuba semula','Translate by hand'=>'Terjemah secara manual','Languages and settings'=>'Bahasa dan tetapan','Engines'=>'Enjin','Translation jobs'=>'Terjemahan kerja','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Tambahkan bahasa kedua di bawah Tranzly dalam menu pentadbir, dan pemilih akan dipaparkan di sini.','Switcher'=>'Penukar','Accessible label'=>'Label boleh diakses','block titleLanguage switcher'=>'Penukar bahasa','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Pautan ke halaman ini dalam setiap bahasa tapak. Ia tidak memaparkan apa-apa sehingga dua atau lebih bahasa disenaraikan.','block keywordlanguage'=>'bahasa','block keywordswitcher'=>'penukar','block keywordtranslation'=>'terjemahan']];